var t=`0183-caprese-salad`;var i=`world-0183`;var l=`IT`;var s=`southern-europe`;var n=4;var r=10;var o={en:`Caprese Salad`,ua:`Салат капрезе`};var g={en:`A classic dish from Italy, featuring tomato, fresh mozzarella, basil. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Італія. Основні складники: помідор, свіжа моцарела, базилік. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var m=[{en:`Cut ripe tomatoes and fresh mozzarella into thick even slices. Arrange alternately with whole basil leaves on a platter.`,ua:`Наріжте стиглі помідори й свіжу моцарелу однаковими товстими скибками. Викладіть почергово з цілими листочками базиліку на таріль.`,t:[`chopping`,`dicing`],m:7,i:[[`tomato`,490,`g`],[`fresh-mozzarella`,360,`g`],[`basil`,35,`g`]]},{en:`Drizzle with olive oil and a little balsamic vinegar, season with salt and freshly ground pepper and serve immediately.`,ua:`Збризніть оливковою олією та невеликою кількістю бальзамічного оцту, приправте сіллю і свіжомеленим перцем та відразу подавайте.`,t:[`tossing`,`seasoning`],m:3,i:[[`extra-virgin-olive-oil`,60,`ml`],[`balsamic-vinegar`,20,`ml`],[`table-salt`,null,`to_taste`],[`ground-black-pepper`,null,`to_taste`]]}];var d={slug:t,id:i,country:`IT`,region:s,servings:4,minutes:10,title:o,text:g,steps:m};export{l as country,d as default,i as id,r as minutes,s as region,n as servings,t as slug,m as steps,g as text,o as title};